mapper.select:
SELECT COALESCE(SUM(pay_amount), 0) AS totalAmount, COALESCE(COUNT(*), 0) AS orderCount, COALESCE(SUM(earned_points), 0) AS totalPoints, COALESCE(SUM(earned_growth), 0) AS totalGrowth FROM t_consume_order WHERE member_id = #{memberId} AND order_status IN (1, 2)
AND pay_time >= #{start}
AND pay_time <= #{end}
AND is_deleted = 0

SELECT COUNT(*)
FROM t_consume_order
WHERE member_id = #{memberId}
  AND order_status IN (1, 2)

      AND pay_time >= #{start}


      AND pay_time <= #{end}

  AND is_deleted = 0

SELECT COUNT(*)
FROM t_member
WHERE create_time >= #{start}
  AND create_time <= #{end}
  AND is_deleted = 0

SELECT
    COALESCE(COUNT(*), 0) AS orderCount,
    COALESCE(SUM(pay_amount), 0) AS totalPayAmount,
    COALESCE(SUM(CASE WHEN member_id IS NOT NULL THEN 1 ELSE 0 END), 0) AS memberOrderCount
FROM t_consume_order
WHERE pay_time >= #{start}
  AND pay_time <= #{end}
  AND order_status IN (1, 2)

      AND store_code = #{storeCode}

  AND is_deleted = 0

SELECT
    COALESCE(SUM(CASE WHEN ci.receive_time IS NOT NULL
        AND ci.receive_time >= #{start}
        AND ci.receive_time <= #{end}
        THEN 1 ELSE 0 END), 0) AS totalIssued,
    COALESCE(SUM(CASE WHEN ci.used_time IS NOT NULL
        AND ci.used_time >= #{start}
        AND ci.used_time <= #{end}
        AND ci.coupon_status = 2
        THEN 1 ELSE 0 END), 0) AS totalUsed,
    COALESCE(SUM(CASE WHEN pl.point_type = 1
        AND pl.create_time >= #{start}
        AND pl.create_time <= #{end}
        THEN pl.change_points ELSE 0 END), 0) AS totalPointsIssued,
    COALESCE(SUM(CASE WHEN pl.point_type = 2
        AND pl.create_time >= #{start}
        AND pl.create_time <= #{end}
        THEN pl.change_points ELSE 0 END), 0) AS totalPointsRedeemed
FROM t_coupon_instance ci
LEFT JOIN t_point_log pl ON 1=1 AND pl.is_deleted = 0
WHERE ci.is_deleted = 0
LIMIT 1

SELECT
    COALESCE(COUNT(DISTINCT o.id), 0) AS totalRefundCount,
    COALESCE(SUM(o.refund_amount), 0) AS totalRefundAmount
FROM t_consume_order o
INNER JOIN t_benefit_use_log bul ON o.order_no = bul.order_no AND bul.is_deleted = 0
WHERE o.order_status = 3
  AND o.is_deleted = 0
  AND bul.benefit_id = #{activityId}

      AND o.refund_time >= #{start}


      AND o.refund_time <= #{end}

SELECT COUNT(DISTINCT m.id)
FROM t_member m
INNER JOIN t_benefit_use_log bul ON m.id = bul.member_id AND bul.is_deleted = 0
WHERE bul.benefit_id = #{activityId}
  AND bul.use_status IN (1, 2)
  AND m.is_deleted = 0

      AND m.create_time >= #{start}


      AND m.create_time <= #{end}
